    <div class="card-body"><?php if ($canManage): ?><form method="post" action="<?= htmlspecialchars(url_for('geraete/' . (int) $device->id . '/pruefungen/neu'), ENT_QUOTES) ?>" class="mb-3"><button class="btn btn-sm btn-primary">Neue Prüfung anlegen</button></form><?php $form($device); else: ?><p><?= nl2br(htmlspecialchars((string) $device->comment)) ?></p><?php endif; ?>
      <?php if (trim((string) ($device->external_number ?? '')) !== ''): ?><p class="small text-body-secondary mb-2">Gerätenummer: <?= htmlspecialchars((string) ($device->external_number ?? '')) ?><?php if (trim((string) ($device->legacy_number ?? '')) !== ''): ?> · alte Nummer: <?= htmlspecialchars((string) $device->legacy_number) ?><?php endif; ?></p><?php endif; ?>
      <?php if ($deviceInspections): ?><h2 class="h6 mt-3">Prüfungen</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Prüfnummer</th><th>Datum</th><th>Prüfart</th><th>Prüfer</th><th>Nächste Prüfung</th><th>Ergebnis</th><th>Raum</th><th>Bericht</th></tr></thead><tbody><?php foreach ($deviceInspections as $inspection): $raw = json_decode((string) ($inspection->raw_json ?? ''), true) ?: []; ?><tr><td><a href="<?= htmlspecialchars(url_for('admin/pruefungen/' . (int) $inspection->id), ENT_QUOTES) ?>"><?= htmlspecialchars((string) ($inspection->external_number ?: '—')) ?></a></td><td><?= htmlspecialchars((string) ($inspection->test_date ?: '—')) ?></td><td><?= htmlspecialchars((string) ($inspection->inspection_type ?: $displayImportValue($raw['type'] ?? '—'))) ?></td><td><?= htmlspecialchars((string) ($inspection->examiner ?: $displayImportValue($raw['created_by'] ?? '—'))) ?></td><td><?= htmlspecialchars((string) ($inspection->next_due_date ?: '—')) ?></td><td><?= htmlspecialchars((string) ($inspection->result_status ?: 'unbekannt')) ?></td><td><?= htmlspecialchars((string) ($inspection->room_snapshot ?: '—')) ?></td><td><?php if (trim((string) ($inspection->report_path ?? '')) !== ''): ?><a href="<?= htmlspecialchars($inspectionReportUrl((int) $inspection->id)) ?>" target="_blank" rel="noopener">PDF</a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    </div>
  </details>
<?php endforeach; ?>
</div>
<?php if ($pages > 1): ?><?php $pageQuery = array_filter($filters ?? [], static fn($value): bool => trim((string) $value) !== ''); ?><nav aria-label="Geräteseiten" class="mt-4"><ul class="pagination justify-content-center flex-wrap"><li class="page-item<?= $page <= 1 ? ' disabled' : '' ?>"><a class="page-link" href="<?= htmlspecialchars(url_for('geraete?' . http_build_query(array_merge($pageQuery, ['page' => max(1, $page - 1)]))), ENT_QUOTES) ?>">Zurück</a></li><?php for ($number = 1; $number <= $pages; $number++): ?><?php if ($number === 1 || $number === $pages || abs($number - $page) <= 2): ?><li class="page-item<?= $number === $page ? ' active' : '' ?>"><a class="page-link" href="<?= htmlspecialchars(url_for('geraete?' . http_build_query(array_merge($pageQuery, ['page' => $number]))), ENT_QUOTES) ?>"><?= $number ?></a></li><?php elseif ($number === 2 || $number === $pages - 1): ?><li class="page-item disabled"><span class="page-link">…</span></li><?php endif; ?><?php endfor; ?><li class="page-item<?= $page >= $pages ? ' disabled' : '' ?>"><a class="page-link" href="<?= htmlspecialchars(url_for('geraete?' . http_build_query(array_merge($pageQuery, ['page' => min($pages, $page + 1)]))), ENT_QUOTES) ?>">Weiter</a></li></ul></nav><?php endif; ?>
